// The transpiled `str.lstrip` follows the Python implementation, since Python is
// the language of the meta-model specifications. Hence, it strips the characters
// (runes).
//
// The built-in `int` is transpiled to
// aascommon.ParseSafeInt, which is stricter than
// the Python `int`. It accepts only an optional sign followed by the ASCII digits,
// and only the safe integers, i.e., the integers within -(2^53 - 1) and 2^53 - 1.
// Otherwise, it panics.
//
// The expected values have been computed with Python, and all the SDKs test
// against the very same cases.

// Test that strings.TrimLeft, to which we transpile `str.lstrip`, strips
// the characters (runes) as Python does.
func TestLstrip(t *testing.T) {
	cases := []struct {
		text     string
		chars    string
		expected string
	}{
		{"000123", "0", "123"},
		{"+-+12", "+-", "12"},
		{"0102", "0", "102"},
		{"", "0", ""},
		{"000", "0", ""},
		{"abc", "", "abc"},
		{"abc", "xyz", "abc"},
		{"abc", "cba", ""},
		{"éé-x", "-é", "x"},
		{"\U0001f600\U0001f600a\U0001f600", "\U0001f600", "a\U0001f600"},
		{"\U0001f601x", "\U0001f600", "\U0001f601x"},
		{"a\U0001f600", "a", "\U0001f600"},
	}

	for _, c := range cases {
		got := strings.TrimLeft(c.text, c.chars)
		if got != c.expected {
			t.Errorf(
				"Expected strings.TrimLeft(%q, %q) to be %q, but got %q",
				c.text, c.chars, c.expected, got,
			)
		}
	}
}

// Test parsing the valid safe integers.
func TestParseSafeInt(t *testing.T) {
	cases := []struct {
		text     string
		expected int64
	}{
		{"0", 0},
		{"-0", 0},
		{"+7", 7},
		{"42", 42},
		{"-42", -42},
		{"0007", 7},
		{"-0042", -42},
		{"0000000000000000000000000000001", 1},
		{"9007199254740991", 9007199254740991},
		{"-9007199254740991", -9007199254740991},
		{"+0009007199254740991", 9007199254740991},
	}

	for _, c := range cases {
		got := aascommon.ParseSafeInt(c.text)
		if got != c.expected {
			t.Errorf(
				"Expected ParseSafeInt(%q) to be %d, but got %d",
				c.text, c.expected, got,
			)
		}
	}
}

// Check that ParseSafeInt panics on text.
func mustPanicOnParseSafeInt(t *testing.T, text string) {
	defer func() {
		if r := recover(); r == nil {
			t.Errorf("Expected ParseSafeInt(%q) to panic, but it did not", text)
		}
	}()

	aascommon.ParseSafeInt(text)
}

// Test that parsing the texts which are not safe integers panics.
func TestParseSafeIntInvalid(t *testing.T) {
	texts := []string{
		"",
		"+",
		"-",
		"+-1",
		" 1",
		"1 ",
		"1_0",
		"1.0",
		"1e3",
		"0x10",
		"\u0665",
		"\uff11",
		"9007199254740992",
		"-9007199254740992",
		"9223372036854775807",
		"999999999999999999999999999999",
	}

	for _, text := range texts {
		mustPanicOnParseSafeInt(t, text)
	}
}

